			title = "Resumen",
			text = [=[Rakaiah es una súcubo que sirve al {link:shadow-council}Consejo de la Sombra{/link} en la {link:jaedenar}Guarida Sombría{/link}. Fue la torturadora del paladín {link:trey-lightforge}Trey Lightforge{/link}, y lo mantuvo sufriendo hasta que murió. Sus restos yacían cerca de los aposentos de ella. Sus amigos del {link:emerald-sanctuary}Santuario Esmeralda{/link} pidieron que la mataran antes de que los restos fueran llevados a casa, para que quien lo había quebrantado no le sobreviviera.]=],
		},
	},
	mentions = {
		{ text = "La venganza de la Luz" },
	},
	bonds = {
		{ id = "trey-lightforge", name = "Trey Lightforge", note = "su víctima" },
	},
})

Translate("esES", "ulathek", {
	title = "Ulathek",
	subtitle = "Siervo de Banehollow",
	found = "Sus aposentos en la Guarida Sombría",
	hint = [=[Lleve el mensaje del señor del terror al siervo que lo traicionó.]=],
	allegiance = "Consejo de la Sombra",
	sections = {
